//! 🧪️ Real queue storage nulls and native payload closure preserve independent actual work under one finite bank.
use super::*;
use crate::queue_bank::{bank,grant,poll,quoted,sync};
use semio_framework_value_retirement::advance_retirement_turn;
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn work(law:&serde_json::Value,key:&str)->u128{u128::from(law[key].as_u64().unwrap())}
#[test]
fn queue_actual_null_and_native_payload_close_use_one_original_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let mut bank=bank();let mut queue=RetirementQueue::default();let d=queue.reserve_demand().unwrap();let g=grant(d);
 for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let((turn,_),heap)=observe(||sync(&mut bank,denied,1,|effect|queue.reserve_step(effect)));assert_eq!(turn.work,work(&law,"deniedWork"));assert_eq!(heap,(0,0));assert!(queue.terminal_is_empty());assert_eq!(queue.reserve_demand().unwrap(),d);}
 let(((turn,_),attempts),heap)=observe(||refuse(||sync(&mut bank,g,1,|effect|queue.reserve_step(effect))));assert_eq!(attempts,1);assert_eq!(turn.work,work(&law,"reserveNullWork"));assert_eq!(heap,(0,0));assert!(turn.result.is_err());bank.post(queue.step_progress(),g,heap);assert!(queue.terminal_is_empty());
 let mut born=0;let mut freed=0;for _ in 0..law["maximumTurns"].as_u64().unwrap(){if queue.has_reserved_slot(){break}let g=grant(queue.reserve_demand().unwrap());let((turn,_),heap)=observe(||sync(&mut bank,g,1,|effect|queue.reserve_step(effect)));let p=turn.result.unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,g,heap);born+=heap.0;freed+=heap.1;}assert!(queue.has_reserved_slot());
 let(value,heap)=observe(||law["text"].as_str().unwrap().to_owned());born+=heap.0;freed+=heap.1;assert_eq!(serde_json::to_value(&value).unwrap(),law["text"]);let mut original=Some(value);let g=grant(queue.admit_owned_demand(original.as_ref().unwrap()).unwrap());let((turn,_),heap)=observe(||sync(&mut bank,g,2,|effect|queue.admit_owned(&mut original,effect)));let spent=turn.work;let p=turn.result.unwrap().unwrap();assert_eq!(spent,work(&law,"transferWork"));assert!(original.is_none());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,g,heap);born+=heap.0;freed+=heap.1;
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if queue.terminal_is_empty(){break}let g=quoted(1,|body|queue.next_demand(body).unwrap());let demand=queue.next_demand(g.maximum_copy_bytes).unwrap();let units=queue.next_computational_work(g.maximum_copy_bytes).unwrap();let(turn,heap)=observe(||advance_retirement_turn(demand,g,|g|{let(turn,_)=poll(&mut bank,g,units,|effect|queue.step(effect));RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|(step,queue.terminal_is_empty()))}}));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,g,heap);born+=heap.0;freed+=heap.1;}
 assert!(queue.terminal_is_empty());let((turn,_),heap)=observe(||poll(&mut bank,Default::default(),0,|effect|queue.step(effect)));assert_eq!(turn.work,work(&law,"cachedWork"));assert_eq!(heap,(0,0));assert!(matches!(turn.result,Ok(RetainedCloneStep::Complete(p))if p==Default::default()));assert_eq!(observe(||drop(queue)).1,(0,0));assert_eq!(born,freed);
}
